-- 0031_ganesha_from_the_book.sql
--
-- GENERATED by scripts/build-ganesha-from-the-book.mjs. Do not hand-edit.
--
-- Three things the book gives the Ganesha pooja that the app did not have,
-- from Sampradaya Vratha Pooja Vidhi (Giri), pp.52-83:
--
--   p.59  the Ganapati Gayatri during the snanam, recited ten times
--   p.79  the rajopachara
--   p.81  the brahmarpanam that closes the rite
--
-- Everything else the transcription turned up was already present, including
-- madhuparkam, the mantra pushpam, brahmaNE svaahaa and the evening savitaa --
-- the last three fixed by 0024. This migration adds only, and replaces nothing.
--
-- Idempotent: every append is guarded on the text it would add.
-- =============================================================================

begin;

-- p.59: The Ganapati Gayatri, which the book directs to be recited ten times during the bath.
update public.pooja_steps set
       mantra_sanskrit = mantra_sanskrit || chr(10) || 'तत्पुरुषाय विद्महे वक्रतुण्डाय धीमहि ।
तन्नो दन्तिः प्रचोदयात् ॥',
       mantra_tamil    = mantra_tamil    || chr(10) || 'தத்புருஷாய வித்மஹே வக்ரதுண்டாய தீமஹி ।
தந்நோ தந்தி꞉ ப்ரசோதயாத் ॥',
       mantra_translit = mantra_translit || chr(10) || 'tatpuruṣāya vidmahe vakratuṇḍāya dhīmahi ।
tanno dantiḥ pracodayāt ॥',
       updated_at      = now()
 where pooja_id = 'ganesha_standard' and step_title_en = 'Snanam & Vastram'
   and mantra_sanskrit not like '%तत्पुरुषाय%';

-- p.79: The rajopachara, offered in the mind for want of the things themselves.
update public.pooja_steps set
       mantra_sanskrit = mantra_sanskrit || chr(10) || 'छत्र–चामर–नृत्त–गीत–वाद्य समस्त राजोपचारार्थं
अक्षतान् समर्पयामि ॥',
       mantra_tamil    = mantra_tamil    || chr(10) || 'சத்ர–சாமர–ந்ருத்த–கீத–வாத்ய ஸமஸ்த ராஜோபசாரார்தம்
அக்ஷதாந் ஸமர்பயாமி ॥',
       mantra_translit = mantra_translit || chr(10) || 'chatra–cāmara–nṛtta–gīta–vādya samasta rājopacārārthaṃ
akṣatān samarpayāmi ॥',
       updated_at      = now()
 where pooja_id = 'ganesha_standard' and step_title_en = 'Mantra Pushpam & Namaskaram'
   and mantra_sanskrit not like '%राजोपचारार्थं%';

-- p.81: The brahmarpanam that closes the rite.
update public.pooja_steps set
       mantra_sanskrit = mantra_sanskrit || chr(10) || 'ॐ तत् सत् ब्रह्मार्पणमस्तु ॥',
       mantra_tamil    = mantra_tamil    || chr(10) || 'ஓம் தத் ஸத் ப்ரஹ்மார்பணமஸ்து ॥',
       mantra_translit = mantra_translit || chr(10) || 'oṃ tat sat brahmārpaṇamastu ॥',
       updated_at      = now()
 where pooja_id = 'ganesha_standard' and step_title_en = 'Kshama Prarthana & Conclusion'
   and mantra_sanskrit not like '%ब्रह्मार्पणमस्तु%';

-- The Ganapati Gayatri carries a count the app has no column for. The book's
-- rubric is dashavaaram japitvaa -- 'having recited ten times' -- so it goes
-- into the instruction, which is the only place a reader will see it.
update public.pooja_steps set
       instruction_en = instruction_en || ' Recite the Ganapati Gayatri (tatpuruṣāya vidmahe) ten times while sprinkling the water.',
       updated_at     = now()
 where pooja_id = 'ganesha_standard' and step_title_en = 'Snanam & Vastram'
   and instruction_en not like '%ten times%';

-- --- assert ------------------------------------------------------------------
do $$
declare n int;
begin
  select count(*) into n from public.pooja_steps
   where pooja_id = 'ganesha_standard' and step_title_en = 'Snanam & Vastram'
     and mantra_sanskrit like '%तत्पुरुषाय%';
  if n <> 1 then raise exception 'Snanam & Vastram did not receive its addition'; end if;

  select count(*) into n from public.pooja_steps
   where pooja_id = 'ganesha_standard' and step_title_en = 'Mantra Pushpam & Namaskaram'
     and mantra_sanskrit like '%राजोपचारार्थं%';
  if n <> 1 then raise exception 'Mantra Pushpam & Namaskaram did not receive its addition'; end if;

  select count(*) into n from public.pooja_steps
   where pooja_id = 'ganesha_standard' and step_title_en = 'Kshama Prarthana & Conclusion'
     and mantra_sanskrit like '%ब्रह्मार्पणमस्तु%';
  if n <> 1 then raise exception 'Kshama Prarthana & Conclusion did not receive its addition'; end if;

  -- Each addition appears exactly once, however many times this is run.
  select (length(mantra_sanskrit) - length(replace(mantra_sanskrit, 'राजोपचारार्थं', '')))
         / length('राजोपचारार्थं') into n from public.pooja_steps
   where pooja_id = 'ganesha_standard' and step_title_en = 'Mantra Pushpam & Namaskaram';
  if n <> 1 then raise exception 'the rajopachara appears % times, expected 1', n; end if;

  -- Nothing structural changed.
  select count(*) into n from public.pooja_steps where pooja_id = 'ganesha_standard';
  if n <> 37 then raise exception 'ganesha has % steps, expected 37', n; end if;

  -- Every step with Devanagari still has the other two scripts.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'ganesha_standard'
     and coalesce(trim(mantra_sanskrit), '') <> ''
     and (mantra_tamil is null or mantra_translit is null);
  if n > 0 then raise exception '% steps are missing a script', n; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

commit;
